	if report.Severity != "degraded" {
		t.Fatalf("severity = %s, want degraded", report.Severity)
	}
	if report.Axes["worktree"].State != "dirty-unindexed" {
		t.Fatalf("worktree axis = %+v", report.Axes["worktree"])
	}
}

